"""Typed decisions and consistency validation; confidence is not probability."""
from dataclasses import asdict
import re
from search.query_numeric import range_contradiction,valid_numeric_domain

EXECUTABLE=('EXECUTABLE','EXECUTABLE_WITH_NOTICE')
MESSAGES={'AMBIGUOUS':'This query could mean more than one thing. Add the field you mean, or use Exact mode for a literal search.',
 'INCOMPLETE':'A search constraint is unfinished. Complete it and search again.',
 'CONTRADICTORY':'These search filters conflict. Edit the query or remove a conflicting filter.',
 'UNSUPPORTED':'This search requests a strict field that this catalogue cannot enforce. Edit that constraint and try again.'}

def decide(plan,kind='EXECUTABLE',reason='VALIDATED',spans=(),fields=(),unresolved=()):
    plan.decision={'decision_type':kind,'reason_code':reason,'relevant_source_spans':list(spans),
      'affected_fields':list(fields),'recognized_candidates':plan.constraint_candidates,
      'unresolved_fragments':list(unresolved),'safe_public_message':MESSAGES.get(kind,''),'parser_version':plan.parser_version}
    if kind not in EXECUTABLE:plan.interpretation_confidence=0.
    return plan

def validate(plan,capabilities=None):
    # Revalidate composed session/control edits too; never broaden on conflict.
    for field in ('rating','year'):
        low,high=getattr(plan,field+'_min'),getattr(plan,field+'_max')
        if range_contradiction(low,high,getattr(plan,field+'_min_exclusive'),getattr(plan,field+'_max_exclusive')):
            return decide(plan,'CONTRADICTORY','INCOMPATIBLE_'+field.upper()+'_BOUNDS',fields=[field])
        if any(v is not None and not valid_numeric_domain(field,v) for v in (low,high)):
            return decide(plan,'UNSUPPORTED','OUT_OF_RANGE_'+field.upper(),fields=[field])
        # A strict boundary at the end of the supported scale has no valid
        # value, even though the operand itself belongs to the scale.
        minimum,maximum=(0,5) if field=='rating' else (1000,2100)
        if low==maximum and getattr(plan,field+'_min_exclusive') or high==minimum and getattr(plan,field+'_max_exclusive'):
            return decide(plan,'UNSUPPORTED','EMPTY_SUPPORTED_'+field.upper()+'_DOMAIN',fields=[field])
    if len(set(plan.exclusive_formats))>1:
        return decide(plan,'CONTRADICTORY','EXCLUSIVE_FORMATS',fields=['format'])
    positives={f for f in plan.formats if f!='BOTH'}|({'ONLINE','PHYSICAL'} if 'BOTH' in plan.formats else set())
    if plan.exclusive_formats and positives-set(plan.exclusive_formats):
        return decide(plan,'CONTRADICTORY','EXCLUSIVE_FORMAT_REQUIREMENT',fields=['format'])
    if positives & set(plan.excluded_formats):return decide(plan,'CONTRADICTORY','FORMAT_INCLUDE_EXCLUDE',fields=['format'])
    from search.query_plan import normalize
    if set(map(normalize,plan.subjects)) & set(map(normalize,plan.exclude_subjects)):
        return decide(plan,'CONTRADICTORY','SUBJECT_INCLUDE_EXCLUDE',fields=['subject'],
                      spans=[{'start':c['source_span_start'],'end':c['source_span_end'],
                              'source_query':c.get('source_query',plan.raw_query)}
                             for c in plan.constraint_candidates if c['field'] in ('subject','excluded_subject','exclude')])
    if capabilities:
        allowed=capabilities.get('formats')
        if allowed is not None and any(f not in allowed for f in plan.formats):
            return decide(plan,'UNSUPPORTED','SCOPE_FORMAT_UNSUPPORTED',fields=['format'])
        for key in ('year','language','availability'):
            present=(plan.year_min is not None or plan.year_max is not None) if key=='year' else bool(getattr(plan,key))
            if present and capabilities.get(key) is False:return decide(plan,'UNSUPPORTED','SCOPE_'+key.upper()+'_UNSUPPORTED',fields=[key])
    return plan

def executable(plan):return plan.decision.get('decision_type','EXECUTABLE') in EXECUTABLE

def normalize(value):
    text = unicodedata.normalize('NFKC', str(value or '')).casefold()
    return ' '.join(re.sub(r'[^\w\s]', ' ', text).split())

class QueryPlan:
    raw_query: str
    mode: str = 'SMART'
    semantic_text: str | None = None
    title_text: str | None = None
    author_text: str | None = None
    subjects: list[str] = field(default_factory=list)
    rating_min: float | None = None
    rating_max: float | None = None
    rating_min_exclusive: bool = False
    rating_max_exclusive: bool = False
    year_min: int | None = None
    year_max: int | None = None
    year_min_exclusive: bool = False
    year_max_exclusive: bool = False
    formats: list[str] = field(default_factory=list)
    availability: str | None = None
    language: str | None = None
    exact_text: str | None = None
    sort: str = 'RELEVANCE'
    interpretation_confidence: float = 1.
    corrections: list[dict] = field(default_factory=list)
    unknown_subject: bool = False
    suggested_subject: str | None = None
    normalized_query: str = ''
    intent: str = 'DISCOVER_TOPIC'
    parser_version: str = PARSER_VERSION
    include_terms: list[str] = field(default_factory=list)
    exclude_terms: list[str] = field(default_factory=list)
    exclude_subjects: list[str] = field(default_factory=list)
    expanded_subjects: list[str] = field(default_factory=list)
    soft_preference: str | None = None
    kg_expansion_used: bool = False
    kg_generation: str | None = None
    constraint_candidates: list[dict] = field(default_factory=list)
    source_spans: list[dict] = field(default_factory=list)
    decision: dict = field(default_factory=dict)
    exclusive_formats: list[str] = field(default_factory=list)
    excluded_formats: list[str] = field(default_factory=list)
    physical_available_only: bool = False

    def ranking_query(self):
        topic=self.semantic_text or ''
        prefix={'LEARN':'introductory beginner guide to ','REFERENCE':'reference handbook for ','RESEARCH':'research studies about '}.get(self.intent,'')
        return prefix+topic

    def cache_key(self,*,library_id=None,hnsw_generation=None):
        import json
        return json.dumps({'scope':library_id or 'GLOBAL','hnsw_generation':hnsw_generation,'plan':asdict(self)}, sort_keys=True, ensure_ascii=False)

    def public(self):
        chips = []
        unsupported=set(self.decision.get('affected_fields',[])) if self.decision.get('decision_type')=='UNSUPPORTED' else set()
        def chip(key, label):
            if key not in unsupported and key.split('_')[0] not in unsupported:chips.append({'key': key, 'label': label})
        if self.semantic_text: chip('topic', 'Topic: ' + self.semantic_text)
        for subject in self.subjects: chip('subject', 'Genre / Subject: ' + subject)
        if self.title_text: chip('title', 'Title / Author: ' + self.title_text)
        if self.author_text: chip('author', 'Author: ' + self.author_text)
        if self.exact_text: chip('exact', 'Exact: ' + self.exact_text)
        if self.rating_min is not None: chip('rating_min', f"Rating: {'>' if self.rating_min_exclusive else '≥'} {self.rating_min:g}")
        if self.rating_max is not None: chip('rating_max', f"Rating: {'<' if self.rating_max_exclusive else '≤'} {self.rating_max:g}")
        if self.year_min is not None: chip('year_min', f"Year: {'>' if self.year_min_exclusive else '≥'} {self.year_min}")
        if self.year_max is not None: chip('year_max', f"Year: {'<' if self.year_max_exclusive else '≤'} {self.year_max}")
        for fmt in self.formats: chip('format', 'Format: ' + {'ONLINE':'Online', 'PHYSICAL':'Physical', 'BOTH':'Physical + Online'}[fmt])
        if self.availability: chip('availability', 'Availability: ' + self.availability.replace('_',' ').title())
        if self.language: chip('language', 'Language: ' + self.language)
        for term in self.exclude_terms:chip('exclude', 'Exclude: '+term)
        for subject in self.exclude_subjects:
            if subject not in self.exclude_terms:chip('exclude', 'Exclude subject: '+subject)
        decision={k:self.decision.get(k) for k in ('decision_type','reason_code','affected_fields','safe_public_message','parser_version')} if self.decision else {'decision_type':'EXECUTABLE','parser_version':self.parser_version}
        return {'mode': self.mode, 'intent':self.intent, 'intent_label':self.intent.replace('_',' ').capitalize(), 'decision':decision,
                'related_concepts':self.expanded_subjects if self.kg_expansion_used else [],
                'preference':self.soft_preference, 'chips': chips, 'corrections': self.corrections,
                'notice': 'No canonical subject matches this query.' if self.unknown_subject else '',
                'suggested_subject': self.suggested_subject}

def sort_books(rows, plan):
    if plan.sort=='TITLE':return sorted(rows,key=lambda r:(normalize(r.get('title')),r.get('work_id',r.get('display_id',''))))
    if plan.sort=='RATING':return sorted(rows,key=lambda r:(-(r.get('average_rating',r.get('rating')) or 0),normalize(r.get('title'))))
    if plan.sort=='NEWEST':return sorted(rows,key=lambda r:(r.get('publication_year') or 0,normalize(r.get('title'))),reverse=True)
    return rows
